import datetime
import os
import pandas as pd
from fly.data.quotation import get_stock_name
from IQCommon.util.fileio_utils import FileIO
from IQEngine.const import RunType
from IQEngine.core.events import EventEnum
from IQEngine.interface import AbstractPlugin
from IQEngine.plugins.plugin_system_trade.enums import EXCHANGE_TYPE_ENUM, SIM_POSITION, TRADE_DIR_PATH
from IQEngine.plugins.plugin_system_trade.function import get_user_info_from_json, position_list_query
from IQEngine.utils import strategy_log
from IQEngine.utils.i18n import get_local_text as _
class PluginSaveHisData(AbstractPlugin):
    def setup(self, engine):
        if engine.config.strategy.run_type != RunType.TRADING:
            return None
        else:
            self.engine = engine
            self.config = self.engine.config.plugins.plugin_system_trade
            self.account_type = self.config.account_type
            self.inter_acc_type = 'STOCK'
            self.op_station = self.config.op_station
            self.account_content = self.config.account_content
            self.trade_id = self.engine.config.strategy.trade_id
            self.business_type = self.config.business_type
            if self.business_type == 'rzrq':
                self.password = get_user_info_from_json().get('rzrq_pwd')
            else:
                self.password = get_user_info_from_json().get('pboxpwd')
            json_dict = get_user_info_from_json()
            self.agw_account = json_dict.get('agw_account')
            self.agw_password = json_dict.get('agw_password')
            self.trade_account = ''
            self.engine.event_bus.append_listener(EventEnum.AFTER_TRADING_END, self.write_stock_position)
    def write_stock_position(self, event):
        self.trade_account = self.engine.algo.broker.trade_account
        position_list = position_list_query(self.trade_account, business_type=self.business_type)
        self.save_sim_position(TRADE_DIR_PATH, self.trade_id, position_list)
    def save_sim_position(self, trade_dir_path, trade_id, data=None):
        columns = ['id', 'positionTime', 'security', 'amount', 'lastPrice', 'marketValue', 'incomeBalance', 'hold_amount', 'enable_amount', 'positionDate', 'cost_price']
        save_data = self.data_list_filer(data)
        currdate = datetime.datetime.now().strftime('%Y%m%d')
        position_bak_file_path = os.path.join(trade_dir_path, 'result', trade_id, SIM_POSITION)
        self.write_position_csv(position_bak_file_path, columns, save_data, ['positionDate'], ['positionDate'], currdate)
    def write_position_csv(self, fileName, fields, data, indexOrder=None, sortOrder=None, delIndex=None):
        if data == []:
            return None
        elif indexOrder is None or sortOrder is None:
            return None
        else:
            df_new = pd.DataFrame(data, columns=fields)
            if not os.path.exists(fileName):
                df_new.sort_values(sortOrder, inplace=True, ascending=False)
                FileIO(fileName).write(df_new, mode='w', data_type='dataframe')
                return None
            else:
                df = FileIO(fileName).read(return_type='dataframe')
                df.set_index(indexOrder, inplace=True)
                df_new.set_index(indexOrder, inplace=True)
                if int(delIndex) in df.index:
                    df.drop(labels=int(delIndex), inplace=True)
                df = df.append(df_new)
                colnames = list(df.columns.values) + list(df.index.names)
                df.reset_index(inplace=True)
                df = df[colnames]
                df.sort_values(sortOrder, inplace=True, ascending=False)
                FileIO(fileName).write(df, mode='w', data_type='dataframe')
    def data_list_filer(self, data):
        save_data = []
        position_id = 1
        position_date = datetime.datetime.now().strftime('%Y%m%d')
        position_time = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        for position in data:
            exchange_type = position.get('exchange_type')
            if exchange_type not in EXCHANGE_TYPE_ENUM.keys():
                continue
            elif self.trade_account.node_type == '7' and exchange_type not in ('1', '2'):
                error_info = f'不支持代码{stock_code!s}的市场类别{exchange_type!s}，不进行持仓信息保存'
                strategy_log.error(_(error_info))
                continue
            else:
                data_item = list()
                data_item.append(position_id)
                data_item.append(position_time)
                stock_code = f"{position.get('stock_code')!s}.{EXCHANGE_TYPE_ENUM[position.get('exchange_type')]!s}"
                stock_name = position.get('stock_name', None)
                if not stock_name:
                    stock_name = get_stock_name(stock_code)[stock_code]
                data_item.append(f'{stock_name!s}({stock_code!s})')
                data_item.append(position.get('current_amount'))
                if 'last_price' in position.keys():
                    last_price = float(position['last_price'])
                else:
                    last_price = self.engine.data_proxy.get_snapshot(stock_code)[stock_code].get('last_px', 0)
                data_item.append(last_price)
                data_item.append(position.get('market_value'))
                data_item.append(position.get('income_balance'))
                data_item.append(position.get('hold_amount'))
                data_item.append(position.get('enable_amount'))
                data_item.append(int(position_date))
                data_item.append(position.get('cost_price'))
                save_data.append(data_item)
                position_id += 1
        else:
            return save_data
    def cleanup(self, code, exception=None):
        return None
    def interface(self):
        return self
def load_plugin():
    return PluginSaveHisData()
